const styles = `:root{color-scheme:dark;--bg:#07111f;--panel:#0d1b2d;--line:#20364e;--text:#eff7ff;--muted:#94aac0;--a:#43dfca;--b:#8b7dff}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 85% 0,#183e68,transparent 32%),var(--bg);font:15px/1.5 Inter,system-ui;color:var(--text)}a{color:var(--a)}.auth{min-height:100vh;display:grid;place-items:center;padding:24px}.box{width:min(450px,100%);background:#0c1b2ddd;border:1px solid var(--line);border-radius:22px;padding:30px;box-shadow:0 25px 80px #0006}.brand{font-weight:900;font-size:20px}.mark{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:12px;margin-right:10px;background:linear-gradient(135deg,var(--a),var(--b));color:#07111f}h1{font-size:30px;margin:28px 0 6px}.muted{color:var(--muted)}label{display:block;margin-top:17px;font-weight:700}input:not([type=checkbox]),select,textarea{width:100%;margin-top:7px;padding:13px 14px;border-radius:11px;border:1px solid var(--line);background:#071522;color:var(--text);font:inherit}button{width:100%;margin-top:22px;padding:13px;border:0;border-radius:11px;background:linear-gradient(135deg,var(--a),#60a8ff);color:#04111e;font-weight:900;cursor:pointer}.error{min-height:22px;color:#ff9d9d;margin-top:12px}.foot{text-align:center;margin-top:20px}.shell{min-height:100vh;display:grid;grid-template-columns:240px 1fr}.side{padding:28px 20px;border-right:1px solid var(--line)}nav{display:grid;gap:8px;margin-top:35px}nav a{padding:11px 13px;text-decoration:none;color:var(--muted)}main{padding:36px;max-width:1200px}.top{display:flex;justify-content:space-between;gap:20px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:28px}.card{padding:22px;background:var(--panel);border:1px solid var(--line);border-radius:17px}.value{font-size:25px;font-weight:900;color:var(--a)}.profile{display:grid;place-items:center;width:46px;height:46px;border-radius:14px;background:linear-gradient(135deg,var(--a),var(--b));color:#07111f;font-weight:900}.metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,1fr);gap:16px;margin-top:16px}.section-title{display:flex;justify-content:space-between;gap:12px;align-items:center}.pill{font-size:12px;padding:5px 9px;border-radius:99px;background:#173448;color:var(--a)}.chart{height:230px;display:flex;align-items:end;gap:12px;padding-top:30px}.chart-col{flex:1;height:100%;display:flex;flex-direction:column;justify-content:end;text-align:center;color:var(--muted)}.bar{position:relative;min-height:8px;border-radius:8px 8px 3px 3px;background:linear-gradient(var(--a),#287b94)}.bar span{position:absolute;top:-25px;left:0;right:0;color:var(--text);font-size:12px}.notice{display:flex;gap:12px;padding:14px 0;border-bottom:1px solid var(--line)}.notice:last-child{border:0}.notice p{margin:3px 0;color:var(--muted)}.notice-dot{width:9px;height:9px;border-radius:50%;background:var(--a);margin-top:7px;flex:none}.empty{padding:35px 0;text-align:center;color:var(--muted)}.skeleton{min-height:112px;opacity:.55}.side{position:sticky;top:0;height:100vh}.active{background:#132a40;border-radius:10px;color:var(--text)!important}.recent{margin-top:16px}.table-wrap{overflow:auto;margin-top:14px}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-size:12px;text-transform:uppercase}.pager{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:16px}.pager button{width:auto;margin:0;padding:9px 14px}.positive{color:var(--a)}.negative{color:#ff9d9d}.mutation-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}input[type=checkbox]{width:auto;margin-right:8px;accent-color:var(--a)}textarea{min-height:120px;margin-top:7px;padding:13px;border:1px solid var(--line);border-radius:11px;background:#071522;color:var(--text);font:inherit}.mutation-grid select{margin-top:7px;padding:13px;border:1px solid var(--line);border-radius:11px;background:#071522;color:var(--text)}@media(max-width:980px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-grid{grid-template-columns:1fr}.mutation-grid{grid-template-columns:1fr}}@media(max-width:700px){.shell{display:block}.side{border:0;padding-bottom:0}nav{display:flex;overflow:auto;margin-top:18px}main{padding:22px}.cards,.metrics{grid-template-columns:1fr}.side{position:static;height:auto}}`;
function layout(title: string, body: string, script = "") {
  const ids = [...body.matchAll(/\sid="([A-Za-z_$][\w$-]*)"/g)]
      .map((match) => match[1]!)
      .filter((id) => !id.includes("-")),
    bindings = [...new Set(ids)]
      .map(
        (id) => `const ${id}=document.getElementById(${JSON.stringify(id)});`,
      )
      .join("");
  return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title} · Nexus SMM</title><style>${styles}</style></head><body>${body}${script ? `<script>${bindings}${script}</script>` : ""}</body></html>`;
}
const client = (api: string) =>
  `const API=${JSON.stringify(api)};const byId=id=>document.getElementById(id);const statuses={PENDING:'Chờ xử lý',PROCESSING:'Đang xử lý',IN_PROGRESS:'Đang chạy',COMPLETED:'Hoàn thành',PARTIAL:'Hoàn thành một phần',FAILED:'Thất bại',CANCELED:'Đã hủy',REFUNDED:'Đã hoàn tiền',PAID:'Đã thanh toán',MANUAL_REVIEW:'Cần kiểm tra',EXPIRED:'Hết hạn',OPEN:'Đang mở',ANSWERED:'Đã trả lời',CUSTOMER_REPLY:'Đã phản hồi',CLOSED:'Đã đóng'};const statusText=value=>statuses[value]||value;const errors={PERMISSION_DENIED:'Bạn không có quyền thực hiện thao tác này.',INSUFFICIENT_BALANCE:'Số dư không đủ.',SERVICE_NOT_FOUND:'Dịch vụ không tồn tại hoặc đã tạm dừng.'};const csrf=()=>document.cookie.split('; ').find(x=>x.startsWith('smm_csrf='))?.split('=').slice(1).join('=')||'';async function call(path,options={}){const r=await fetch(API+path,{credentials:'include',...options,headers:{'content-type':'application/json',...(csrf()?{'x-csrf-token':csrf()}:{}),...(options.headers||{})}});const v=await r.json();if(r.status===401){location.href='/login';throw new Error('Vui lòng đăng nhập.')}if(r.status===403&&path.startsWith('/api/v1/admin')){document.body.innerHTML='<main class="auth"><section class="box"><h1>Không có quyền truy cập</h1><p>Bạn không có quyền truy cập khu vực quản trị.</p><a href="/dashboard">Quay về trang khách hàng</a></section></main>';throw new Error('Bạn không có quyền thực hiện thao tác này.')}if(!r.ok)throw new Error(errors[v.error?.code]||v.error?.message||'Có lỗi xảy ra. Vui lòng thử lại.');return v.data}`;
const navLink = (active: string, path: string, label: string) =>
  `<a class="${active === path ? "active" : ""}" href="${path}">${label}</a>`;
const customerNavigation = (active: string) =>
  `<div class="brand"><span class="mark">N</span>Nexus Panel</div><nav>${navLink(active, "/dashboard", "Tổng quan")}${navLink(active, "/services", "Dịch vụ")}${navLink(active, "/orders", "Đơn hàng")}${navLink(active, "/deposit", "Nạp tiền")}${navLink(active, "/wallet", "Ví của tôi")}${navLink(active, "/api-docs", "API")}${navLink(active, "/support", "Hỗ trợ")}<a class="${active === "/notifications" ? "active" : ""}" href="/notifications" aria-label="Thông báo">🔔</a>${navLink(active, "/account", "Tài khoản")}<a href="#" id="logout">Đăng xuất</a></nav>`;
export function authPage(kind: "login" | "register" | "forgot", api: string) {
  const data =
    kind === "login"
      ? {
          title: "Đăng nhập",
          fields: `<label>Email<input name="email" type="email" autocomplete="email" required></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required></label>`,
          endpoint: "/api/v1/auth/login",
          foot: `<a href="/forgot-password">Quên mật khẩu?</a> · <a href="/register">Tạo tài khoản</a>`,
        }
      : kind === "register"
        ? {
            title: "Tạo tài khoản",
            fields: `<label>Email<input name="email" type="email" required></label><label>Tên người dùng<input name="username" minlength="3" required></label><label>Mật khẩu<input name="password" type="password" minlength="12" required></label>`,
            endpoint: "/api/v1/auth/register",
            foot: `Đã có tài khoản? <a href="/login">Đăng nhập</a>`,
          }
        : {
            title: "Khôi phục mật khẩu",
            fields: `<label>Email<input name="email" type="email" required></label>`,
            endpoint: "/api/v1/auth/forgot-password",
            foot: `<a href="/login">Quay lại đăng nhập</a>`,
          };
  const body = `<div class="auth"><section class="box"><div class="brand"><span class="mark">N</span>Nexus Panel</div><h1>${data.title}</h1><p class="muted">Bảo mật phiên đăng nhập và dữ liệu tài khoản.</p><form id="form">${data.fields}<button>${data.title}</button><div class="error" id="message" role="alert"></div></form><div class="foot muted">${data.foot}</div></section></div>`;
  const script = `${client(api)};form.addEventListener('submit',async e=>{e.preventDefault();message.textContent='';const values=Object.fromEntries(new FormData(form));try{const data=await call('${data.endpoint}',{method:'POST',body:JSON.stringify(values)});${kind === "forgot" ? "message.textContent=data.developmentToken?'Token development: '+data.developmentToken:'Nếu email tồn tại, hướng dẫn đã được tạo.'" : "location.href=data.access?.roles?.includes('SUPER_ADMIN')?'/admin':'/dashboard'"}}catch(error){message.textContent=error.message}})`;
  return layout(data.title, body, script);
}
export function resetPasswordPage(api: string, token: string) {
  const body = `<div class="auth"><section class="box"><div class="brand"><span class="mark">N</span>Nexus Panel</div><h1>Đặt lại mật khẩu</h1><p class="muted">Mật khẩu mới cần có chữ hoa, chữ thường và chữ số.</p><form id="form"><label>Mật khẩu mới<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><button id="submit">Đổi mật khẩu</button><div id="message" class="error" role="alert"></div></form></section></div>`;
  const script = `${client(api)};form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;message.textContent='';try{await call('/api/v1/auth/reset-password',{method:'POST',body:JSON.stringify({token:${JSON.stringify(token)},password:new FormData(form).get('password')})});message.textContent='Đổi mật khẩu thành công. Đang chuyển đến đăng nhập…';setTimeout(()=>location.href='/login',800)}catch(error){message.textContent=error.message;submit.disabled=false}}`;
  return layout("Đặt lại mật khẩu", body, script);
}
export function panelPage(admin: boolean, api: string) {
  const endpoint = admin
    ? "/api/v1/admin/overview"
    : "/api/v1/customer/overview";
  const navigation = admin
    ? adminNavigation("/admin")
    : customerNavigation("/dashboard");
  const recent = admin
    ? `<section class="card recent"><div class="section-title"><b>Đơn hàng gần đây</b><span class="muted">Snapshot vận hành</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Trạng thái</th><th>Doanh thu</th><th>Profit</th><th>Thời gian</th></tr></thead><tbody id="recentOrders"><tr><td colspan="5" class="empty">Đang tải…</td></tr></tbody></table></div></section>`
    : "";
  const quick = admin
      ? ""
      : `<section class="card recent"><div class="section-title"><b>Thao tác nhanh</b></div><div class="mutation-grid"><a class="card" href="/orders">Tạo đơn mới</a><a class="card" href="/deposit">Nạp tiền</a><a class="card" href="/orders">Xem đơn hàng</a><a class="card" href="/support">Liên hệ hỗ trợ</a></div></section>`,
    body = `<div class="shell"><aside class="side">${navigation}</aside><main><div class="top"><div><div class="muted">${admin ? "KHU VỰC QUẢN TRỊ" : "TRANG KHÁCH HÀNG"}</div><h1 id="welcome">Đang tải…</h1><p class="muted">Theo dõi tài khoản và hoạt động gần đây của bạn.</p></div><div class="profile" id="profile">•••</div></div>${quick}<section class="cards metrics" id="metrics"><article class="card skeleton"></article><article class="card skeleton"></article><article class="card skeleton"></article></section><section class="dashboard-grid"><article class="card"><div class="section-title"><div><b>Hoạt động 7 ngày</b><div class="muted">Số đơn hàng theo ngày</div></div></div><div class="chart" id="chart" aria-label="Biểu đồ đơn hàng bảy ngày"></div></article><article class="card"><div class="section-title"><b>Thông báo gần đây</b><span class="pill" id="unread">0 chưa đọc</span></div><div id="notifications" class="notifications"><div class="empty">Đang tải…</div></div></article></section><div class="error" id="message"></div>${recent}</main></div>`;
  const dashboardScript = admin
    ? `if(data.dashboard){const d=data.dashboard;metrics.innerHTML=card('Tổng users',d.users.total,d.users.active+' active · '+d.users.today+' hôm nay · '+d.users.sevenDays+' / 7 ngày')+card('Tổng orders',d.orders.total,d.orders.active+' đang chạy')+card('Hoàn thành',d.orders.completed,d.orders.failed+' lỗi/hủy')+card('Doanh thu',money(d.money.revenue,d.money.currency),'Order charge snapshot')+card('Provider cost',money(d.money.providerCost,d.money.currency),'Chi phí snapshot')+card('Gross profit',money(d.money.profit,d.money.currency),'Lợi nhuận snapshot')+card('Đã nạp',money(d.money.deposits,d.money.currency),d.depositsPending+' pending')+card('Tickets',d.openTickets,'Đang mở')+card('Providers',d.providers.active+' / '+(d.providers.active+d.providers.inactive),d.providers.inactive+' inactive')+card('Services',d.services.active+' / '+(d.services.active+d.services.inactive),d.services.inactive+' inactive');recentOrders.innerHTML=d.recentOrders.length?d.recentOrders.map(o=>'<tr><td>#'+escapeHtml(o.id)+'</td><td><span class="pill">'+escapeHtml(o.status)+'</span></td><td>'+money(o.charge,d.money.currency)+'</td><td>'+money(o.profit,d.money.currency)+'</td><td>'+new Date(o.createdAt).toLocaleString('vi-VN')+'</td></tr>').join(''):'<tr><td colspan="5" class="empty">Chưa có đơn hàng.</td></tr>';const max=Math.max(1,...d.activity.map(x=>x.orders));chart.innerHTML=d.activity.map(x=>'<div class="chart-col" title="Revenue '+escapeHtml(x.revenue)+' · Profit '+escapeHtml(x.profit)+'"><div class="bar" style="height:'+Math.max(8,x.orders/max*100)+'%"><span>'+x.orders+'</span></div><small>'+x.date.slice(5)+'</small><small>R '+escapeHtml(x.revenue)+'</small><small>P '+escapeHtml(x.profit)+'</small></div>').join('');unread.textContent=d.alerts.length+' cảnh báo';notifications.innerHTML=d.alerts.length?d.alerts.map(a=>'<div class="notice"><span class="notice-dot"></span><div><b>'+escapeHtml(a.message)+'</b><p>'+a.count+' mục cần xử lý</p></div></div>').join(''):'<div class="empty">Không có cảnh báo vận hành.</div>'}`
    : `if(data.dashboard){const d=data.dashboard;metrics.innerHTML=card('Số dư',money(d.balance,d.currency),'Ví khả dụng')+card('Tổng đơn',d.totalOrders,d.activeOrders+' đang xử lý')+card('Hoàn thành',d.completedOrders,'Đơn đã hoàn tất')+card('Đã chi',money(d.totalSpent,d.currency),'Chi phí đơn hàng')+card('Đã nạp',money(d.totalDeposited,d.currency),'Nạp tiền thành công')+card('Ticket mở',d.openTickets,'Cần theo dõi');const max=Math.max(1,...d.activity.map(x=>x.orders));chart.innerHTML=d.activity.map(x=>'<div class="chart-col"><div class="bar" style="height:'+Math.max(8,x.orders/max*100)+'%"><span>'+x.orders+'</span></div><small>'+x.date.slice(5)+'</small></div>').join('');unread.textContent=d.unreadNotifications+' chưa đọc';notifications.innerHTML=d.notifications.length?d.notifications.map(n=>'<div class="notice"><span class="notice-dot"></span><div><b>'+escapeHtml(n.title)+'</b><p>'+escapeHtml(n.body)+'</p><small class="muted">'+new Date(n.createdAt).toLocaleString('vi-VN')+'</small></div></div>').join(''):'<div class="empty">Bạn chưa có thông báo.</div>'}`;
  const script = `${client(api)};const money=(v,c='USD')=>c+' '+String(v??'0');const card=(label,value,note='')=>'<article class="card"><div class="muted">'+label+'</div><div class="value">'+value+'</div><small class="muted">'+note+'</small></article>';(async()=>{try{const data=await call('${endpoint}');welcome.textContent='Xin chào, '+data.user.username;profile.textContent=data.user.username.slice(0,2).toUpperCase();${dashboardScript}}catch(e){${admin ? "message.textContent=e.message;setTimeout(()=>location.href='/dashboard',1200)" : "location.href='/login'"}}})();function escapeHtml(v){const e=document.createElement('div');e.textContent=String(v);return e.innerHTML}logout.addEventListener('click',async e=>{e.preventDefault();try{await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'}catch(e){message.textContent=e.message}})`;
  return layout(admin ? "Admin Panel" : "Customer Panel", body, script);
}
export function walletPage(api: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/wallet")}</aside><main><div class="top"><div><div class="muted">CUSTOMER WALLET</div><h1>Ví của bạn</h1><p class="muted">Lịch sử ledger chỉ đọc, được đồng bộ trực tiếp từ PostgreSQL.</p></div></div><section class="cards"><article class="card"><div class="muted">Số dư khả dụng</div><div class="value" id="balance">Đang tải…</div><small class="muted" id="updated"></small></article></section><section class="card recent"><div class="section-title"><b>Lịch sử giao dịch</b><span class="pill" id="count">0 giao dịch</span></div><div class="table-wrap"><table><thead><tr><th>Loại</th><th>Số tiền</th><th>Số dư sau</th><th>Tham chiếu</th><th>Thời gian</th></tr></thead><tbody id="transactions"><tr><td colspan="5" class="empty">Đang tải…</td></tr></tbody></table></div><div class="pager"><button id="previous">Trước</button><span id="pageLabel">Trang 1</span><button id="next">Sau</button></div></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};let page=1,pages=1;const money=(v,c)=>c+' '+String(v);async function load(){try{const [wallet,history]=await Promise.all([call('/api/v1/customer/wallet'),call('/api/v1/customer/wallet/transactions?page='+page+'&limit=20')]);balance.textContent=money(wallet.balance,wallet.currency);updated.textContent='Cập nhật '+new Date(wallet.updatedAt).toLocaleString('vi-VN');count.textContent=history.total+' giao dịch';pages=Math.max(1,history.pages);pageLabel.textContent='Trang '+page+' / '+pages;previous.disabled=page<=1;next.disabled=page>=pages;transactions.innerHTML=history.items.length?history.items.map(x=>'<tr><td><span class="pill">'+escapeHtml(x.type)+'</span></td><td class="'+(String(x.amount).startsWith('-')?'negative':'positive')+'">'+escapeHtml(x.amount)+'</td><td>'+escapeHtml(x.balanceAfter)+'</td><td>'+escapeHtml(x.referenceId||'—')+'</td><td>'+new Date(x.createdAt).toLocaleString('vi-VN')+'</td></tr>').join(''):'<tr><td colspan="5" class="empty">Chưa có giao dịch.</td></tr>'}catch(e){if(e.message==='Authentication required')location.href='/login';else message.textContent=e.message}}function escapeHtml(v){const e=document.createElement('div');e.textContent=String(v);return e.innerHTML}previous.onclick=()=>{if(page>1){page--;load()}};next.onclick=()=>{if(page<pages){page++;load()}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load()`;
  return layout("Ví & giao dịch", body, script);
}
export function adminWalletPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/wallet")}</aside><main><div class="top"><div><div class="muted">ADMIN WALLET CONTROL</div><h1>Điều chỉnh ví có kiểm soát</h1><p class="muted">Mỗi thao tác tạo ledger và AuditLog bất biến.</p></div></div><section class="card"><label>User UUID<input id="userId" placeholder="xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"></label><button id="load">Tải ví</button><div class="value" id="adminBalance">—</div></section><section class="card recent"><div class="section-title"><b>Money mutation</b><span class="pill">wallets.adjust</span></div><div class="mutation-grid"><label>Số tiền<input id="amount" inputmode="decimal" placeholder="10.00000000"></label><label>Loại<select id="mutationType"><option>ADMIN_ADD</option><option>ADMIN_SUBTRACT</option><option>ADJUSTMENT</option></select></label><label>Hướng adjustment<select id="direction"><option value="credit">Credit</option><option value="debit">Debit</option></select></label><label>Mô tả<input id="description" maxlength="500"></label></div><button id="mutate">Ghi transaction</button></section><section class="card recent"><div class="section-title"><b>Ledger gần đây</b><span class="pill" id="ledgerCount">0</span></div><div class="table-wrap"><table><thead><tr><th>Loại</th><th>Amount</th><th>Before</th><th>After</th><th>Thời gian</th></tr></thead><tbody id="ledger"><tr><td colspan="5" class="empty">Nhập User UUID để tải.</td></tr></tbody></table></div></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};const valid=()=>/^[0-9a-f-]{36}$/.test(userId.value);async function refresh(){message.textContent='';if(!valid()){message.textContent='User UUID không hợp lệ';return}try{const [wallet,history]=await Promise.all([call('/api/v1/admin/wallets/'+userId.value),call('/api/v1/admin/wallets/'+userId.value+'/transactions?page=1&limit=20')]);adminBalance.textContent=wallet.currency+' '+wallet.balance;ledgerCount.textContent=history.total+' transactions';ledger.innerHTML=history.items.length?history.items.map(x=>'<tr><td>'+x.type+'</td><td>'+x.amount+'</td><td>'+x.balanceBefore+'</td><td>'+x.balanceAfter+'</td><td>'+new Date(x.createdAt).toLocaleString('vi-VN')+'</td></tr>').join(''):'<tr><td colspan="5" class="empty">Ledger trống.</td></tr>'}catch(e){message.textContent=e.message}}load.onclick=refresh;mutate.onclick=async()=>{if(!valid())return refresh();try{await call('/api/v1/admin/wallets/'+userId.value+'/mutations',{method:'POST',headers:{'idempotency-key':'admin:'+crypto.randomUUID()},body:JSON.stringify({amount:amount.value,type:mutationType.value,direction:direction.value,description:description.value})});await refresh()}catch(e){message.textContent=e.message}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'}`;
  return layout("Admin Wallet", body, script);
}
export const dashboardPage = panelPage(false, "http://localhost:4000");

export function servicesPage(api: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/services")}</aside><main><div class="top"><div><div class="muted">SERVICE CATALOG</div><h1>Danh mục dịch vụ</h1><p class="muted">Giá bán được tính theo price group của tài khoản.</p></div></div><section class="card mutation-grid"><label>Tìm kiếm<input id="search" placeholder="Tên dịch vụ"></label><label>Danh mục<select id="category"><option value="">Tất cả</option></select></label></section><section class="card recent"><div class="section-title"><b>Dịch vụ đang hoạt động</b><span class="pill" id="count">0</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Tên</th><th>Rate / 1000</th><th>Min–Max</th><th>Refill</th><th>Cancel</th></tr></thead><tbody id="rows"><tr><td colspan="6" class="empty">Đang tải…</td></tr></tbody></table></div><div class="pager"><button id="previous">Trước</button><span id="pageLabel">Trang 1</span><button id="next">Sau</button></div></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};let page=1,pages=1;const esc=v=>{const d=document.createElement('div');d.textContent=String(v);return d.innerHTML};async function load(){rows.innerHTML='<tr><td colspan="6" class="empty">Đang tải…</td></tr>';try{const q=new URLSearchParams({page:String(page),limit:'25'});if(category.value)q.set('category',category.value);if(search.value)q.set('search',search.value);const d=await call('/api/v1/customer/catalog?'+q);pages=Math.max(1,d.pages);count.textContent=d.total+' dịch vụ';pageLabel.textContent='Trang '+page+' / '+pages;if(category.options.length===1)d.categories.forEach(x=>category.add(new Option(x.name,x.slug)));rows.innerHTML=d.services.length?d.services.map(x=>'<tr><td>'+esc(x.id.slice(0,8))+'</td><td><b>'+esc(x.name)+'</b><div class="muted">'+esc(x.averageTime||'—')+'</div></td><td class="positive">'+esc(x.rate)+'</td><td>'+x.min+'–'+x.max+'</td><td>'+(x.refill?'Có':'Không')+'</td><td>'+(x.cancel?'Có':'Không')+'</td></tr>').join(''):'<tr><td colspan="6" class="empty">Không tìm thấy dịch vụ.</td></tr>';previous.disabled=page<=1;next.disabled=page>=pages}catch(e){message.textContent=e.message}};search.oninput=()=>{page=1;clearTimeout(window.s);window.s=setTimeout(load,250)};category.onchange=()=>{page=1;load()};previous.onclick=()=>{page--;load()};next.onclick=()=>{page++;load()};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load()`;
  return layout("Dịch vụ", body, script);
}

export function adminCatalogPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/catalog")}</aside><main><div class="top"><div><div class="muted">SERVICES.MANAGE</div><h1>Catalog & pricing</h1><p class="muted">Quản lý category, service và chính sách giá chính xác NUMERIC.</p></div></div><section class="dashboard-grid"><form class="card" id="categoryForm"><b>Tạo category</b><label>Tên<input name="name" required></label><label>Slug<input name="slug" pattern="[a-z0-9-]+" required></label><button>Tạo category</button></form><form class="card" id="groupForm"><b>Tạo price group</b><label>Tên<input name="name" required></label><label>Code<input name="code" required></label><button>Tạo price group</button></form></section><form class="card recent" id="serviceForm"><b>Tạo service</b><div class="mutation-grid"><label>Category<select name="categoryId" id="serviceCategory" required></select></label><label>Tên<input name="name" required></label><label>Type<input name="type" value="DEFAULT" required></label><label>Rate / 1000<input name="rate" inputmode="decimal" required></label><label>Provider cost<input name="providerCost" inputmode="decimal" required></label><label>Min<input name="min" type="number" min="1" required></label><label>Max<input name="max" type="number" min="1" required></label></div><button>Tạo service</button></form><form class="card recent" id="ruleForm"><b>Upsert pricing rule</b><div class="mutation-grid"><label>Price group<select name="priceGroupId" id="ruleGroup"></select></label><label>Service<select name="serviceId" id="ruleService"></select></label><label>Fixed rate<input name="fixedRate" inputmode="decimal"></label><label>Markup %<input name="markupPercent" inputmode="decimal"></label><label>Fixed profit<input name="fixedProfit" inputmode="decimal"></label><label>Minimum profit<input name="minProfit" inputmode="decimal" value="0"></label></div><button>Lưu pricing rule</button></form><form class="card recent" id="mappingForm"><b>Provider mapping</b><div class="mutation-grid"><label>Service<select name="serviceId" id="mappingService"></select></label><label>Provider service<select name="providerServiceId" id="providerService"></select></label><label>Priority<input name="priority" type="number" value="100"></label><label>Min profit<input name="minProfit" value="0"></label><label><input id="mappingActive" type="checkbox" checked> Mapping active</label></div><button>Save mapping</button></form><section class="card recent"><div class="section-title"><b>Services</b><span class="pill" id="count">Đang tải</span></div><div class="table-wrap"><table><thead><tr><th>Tên</th><th>Rate</th><th>Cost</th><th>Min–Max</th><th>Trạng thái</th><th>Action</th></tr></thead><tbody id="rows"></tbody></table></div></section><section class="dashboard-grid recent"><article class="card"><h2>Categories</h2><div id="categoryRows"></div></article><article class="card"><h2>Price groups</h2><div id="groupRows"></div></article></section><section class="card recent"><h2>Pricing rules & provider mappings</h2><div id="ruleRows"></div><div id="mappingRows"></div></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};let state;const esc=v=>{const d=document.createElement('div');d.textContent=String(v);return d.innerHTML};async function load(){try{state=await call('/api/v1/admin/catalog');serviceCategory.innerHTML=state.categories.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');ruleGroup.innerHTML=state.priceGroups.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');ruleService.innerHTML=state.services.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join('');mappingService.innerHTML=ruleService.innerHTML;providerService.innerHTML=state.providerServices.map(x=>'<option value="'+x.id+'">'+esc(x.name)+' · '+esc(x.rate)+'</option>').join('');count.textContent=state.services.length+' services';rows.innerHTML=state.services.length?state.services.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.rate)+'</td><td>'+esc(x.providerCost)+'</td><td>'+x.min+'–'+x.max+'</td><td><span class="pill">'+(x.active?'Active':'Inactive')+'</span></td><td><button style="margin:0;width:auto" data-id="'+x.id+'" data-active="'+x.active+'">'+(x.active?'Disable':'Enable')+'</button></td></tr>').join(''):'<tr><td colspan="6" class="empty">Chưa có service.</td></tr>';document.querySelectorAll('[data-active]').forEach(b=>b.onclick=async()=>{if(!confirm('Xác nhận thay đổi trạng thái?'))return;await call('/api/v1/admin/catalog/services/'+b.dataset.id+'/update',{method:'POST',body:JSON.stringify({active:b.dataset.active!=='true'})});load()});categoryRows.innerHTML=state.categories.map(c=>'<p>'+esc(c.name)+' <button style="width:auto;margin:2px" data-category="'+c.id+'">Edit</button></p>').join('')||'<p class="empty">No categories</p>';groupRows.innerHTML=state.priceGroups.map(g=>'<p>'+esc(g.name)+' · '+g.active+' <button style="width:auto;margin:2px" data-group="'+g.id+'">Edit</button></p>').join('')||'<p class="empty">No groups</p>';ruleRows.innerHTML='<h3>Rules</h3>'+state.priceRules.map(r=>'<button style="width:auto;margin:2px" data-rule="'+r.serviceId+'|'+r.priceGroupId+'">'+esc(r.serviceId.slice(0,8))+' · '+(r.fixedRate||r.markupPercent||'default')+'</button>').join('');mappingRows.innerHTML='<h3>Mappings</h3>'+state.mappings.map(m=>'<button style="width:auto;margin:2px" data-mapping="'+m.serviceId+'|'+m.providerServiceId+'|'+m.priority+'|'+m.active+'">'+esc(m.serviceId.slice(0,8))+' → '+esc(m.providerServiceId.slice(0,8))+' · P'+m.priority+' · '+m.active+'</button>').join('');document.querySelectorAll('[data-category]').forEach(b=>b.onclick=async()=>{const c=state.categories.find(x=>x.id===b.dataset.category),name=prompt('Category name',c.name);if(name){await call('/api/v1/admin/catalog/categories/'+c.id+'/update',{method:'POST',body:JSON.stringify({name})});load()}});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=async()=>{const g=state.priceGroups.find(x=>x.id===b.dataset.group),name=prompt('Price group name',g.name);if(name){await call('/api/v1/admin/catalog/price-groups/'+g.id+'/update',{method:'POST',body:JSON.stringify({name,active:g.active})});load()}});document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>{const [serviceId,priceGroupId]=b.dataset.rule.split('|'),r=state.priceRules.find(x=>x.serviceId===serviceId&&x.priceGroupId===priceGroupId);ruleService.value=serviceId;ruleGroup.value=priceGroupId;ruleForm.fixedRate.value=r.fixedRate||'';ruleForm.markupPercent.value=r.markupPercent||'';ruleForm.fixedProfit.value=r.fixedProfit||'';ruleForm.minProfit.value=r.minProfit||'0';ruleForm.scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-mapping]').forEach(b=>b.onclick=()=>{const [serviceId,providerServiceId,priority,active]=b.dataset.mapping.split('|');mappingService.value=serviceId;providerService.value=providerServiceId;mappingForm.priority.value=priority;mappingActive.checked=active==='true';mappingForm.scrollIntoView({behavior:'smooth'})})}catch(e){message.textContent=e.message}}async function submit(form,path){const body=Object.fromEntries(new FormData(form));await call(path,{method:'POST',body:JSON.stringify(body)});form.reset();await load()}categoryForm.onsubmit=async e=>{e.preventDefault();try{await submit(categoryForm,'/api/v1/admin/catalog/categories')}catch(x){message.textContent=x.message}};groupForm.onsubmit=async e=>{e.preventDefault();try{await submit(groupForm,'/api/v1/admin/catalog/price-groups')}catch(x){message.textContent=x.message}};serviceForm.onsubmit=async e=>{e.preventDefault();try{await submit(serviceForm,'/api/v1/admin/catalog/services')}catch(x){message.textContent=x.message}};ruleForm.onsubmit=async e=>{e.preventDefault();try{await submit(ruleForm,'/api/v1/admin/catalog/price-rules')}catch(x){message.textContent=x.message}};mappingForm.onsubmit=async e=>{e.preventDefault();try{await call('/api/v1/admin/catalog/mappings',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(mappingForm)),active:mappingActive.checked})});mappingForm.reset();mappingActive.checked=true;await load()}catch(x){message.textContent=x.message}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load()`;
  return layout("Catalog management", body, script);
}

export function adminProvidersPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/providers")}</aside><main><h1>Nhà cung cấp</h1><p class="muted">Credentials được mã hóa; API chỉ hiển thị giá trị masked.</p><form class="card mutation-grid" id="form"><label>Name<input name="name" required></label><label>API URL<input name="apiUrl" type="url" required></label><label>API key<input name="apiKey" type="password" required></label><label>Currency<input name="currency" value="USD"></label><button>Tạo provider (inactive)</button></form><section class="card recent"><div class="table-wrap"><table><thead><tr><th>Tên</th><th>Key</th><th>Trạng thái</th><th>Số dư</th><th>Thao tác</th></tr></thead><tbody id="rows"><tr><td colspan="5">Đang tải…</td></tr></tbody></table></div></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};async function load(){try{const x=await call('/api/v1/admin/providers');rows.innerHTML=x.length?x.map(p=>'<tr><td><a href="/admin/providers/'+p.id+'">'+p.name+'</a></td><td>'+p.apiKeyMasked+'</td><td>'+p.status+'</td><td>'+(p.balance??'—')+'</td><td><button style="width:auto;margin:2px" data-test="'+p.id+'">Test</button><button style="width:auto;margin:2px" data-sync="'+p.id+'">Sync</button><button style="width:auto;margin:2px" data-toggle="'+p.id+'" data-status="'+p.status+'">'+(p.status==='INACTIVE'?'Bật':'Tắt')+'</button></td></tr>').join(''):'<tr><td colspan="5" class="empty">Chưa có provider.</td></tr>';document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>action(b.dataset.test,'test'));document.querySelectorAll('[data-sync]').forEach(b=>b.onclick=()=>action(b.dataset.sync,'sync'));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{if(confirm('Change provider status?')){await call('/api/v1/admin/providers/'+b.dataset.toggle,{method:'POST',body:JSON.stringify({status:b.dataset.status==='INACTIVE'?'ACTIVE':'INACTIVE'})});load()}})}catch(e){message.textContent=e.message}}async function action(id,a){try{const x=await call('/api/v1/admin/providers/'+id+'/'+a,{method:'POST',body:'{}'});message.textContent=a==='sync'?'Synced '+x.received+' services':'Balance '+x.balance+' '+x.currency;load()}catch(e){message.textContent=e.message}}form.onsubmit=async e=>{e.preventDefault();try{await call('/api/v1/admin/providers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();load()}catch(e){message.textContent=e.message}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load()`;
  return layout("Providers", body, script);
}

export function adminProviderDetailPage(api: string, id: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/providers")}</aside><main><a href="/admin/providers">← Providers</a><h1>Chi tiết nhà cung cấp</h1><form id="form" class="card mutation-grid"><label>Name<input name="name" id="name" required></label><label>API URL<input name="apiUrl" id="apiUrl" type="url" required></label><label>New API key<input name="apiKey" type="password" placeholder="Để trống để giữ giá trị hiện tại"></label><label>Currency<input name="currency" id="currency"></label><label>Status<select name="status" id="providerStatus"><option>ACTIVE</option><option>DEGRADED</option><option>INACTIVE</option></select></label><label>Timeout ms<input name="timeoutMs" id="timeoutMs" type="number" min="1000"></label><button>Lưu nhà cung cấp</button></form><section class="card recent"><div class="section-title"><h2>Dịch vụ nhà cung cấp</h2><span id="serviceCount" class="pill">0</span></div><div id="services" class="table-wrap"></div></section><section class="card recent"><h2>Nhật ký đã ẩn dữ liệu nhạy cảm</h2><div id="logs"></div></section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};async function load(){const p=await call('/api/v1/admin/providers/${id}');name.value=p.name;apiUrl.value=p.apiUrl;currency.value=p.currency;providerStatus.value=p.status;timeoutMs.value=p.timeoutMs;serviceCount.textContent=p.services.length;services.innerHTML=p.services.length?'<table><thead><tr><th>External ID</th><th>Tên</th><th>Rate</th><th>Min–Max</th><th>Trạng thái</th></tr></thead><tbody>'+p.services.map(s=>'<tr><td>'+escapeHtml(s.externalId)+'</td><td>'+escapeHtml(s.name)+'</td><td>'+s.rate+'</td><td>'+s.min+'–'+s.max+'</td><td>'+s.active+'</td></tr>').join('')+'</tbody></table>':'<p class="empty">No synced services.</p>';logs.innerHTML=p.logs.length?p.logs.map(l=>'<article class="notice"><div><b>'+escapeHtml(l.operation)+'</b><p>'+l.status+' · '+(l.errorCode||'OK')+'</p><small>'+new Date(l.createdAt).toLocaleString()+'</small></div></article>').join(''):'<p class="empty">No provider logs.</p>'}function escapeHtml(v){const d=document.createElement('div');d.textContent=String(v);return d.innerHTML}form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));if(!data.apiKey)delete data.apiKey;try{await call('/api/v1/admin/providers/${id}',{method:'POST',body:JSON.stringify(data)});message.textContent='Provider saved.';load()}catch(e){message.textContent=e.message}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`;
  return layout("Provider detail", body, script);
}

export function ordersPage(api: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/orders")}</aside><main><h1>Tạo đơn hàng</h1><p class="muted">Chọn dịch vụ, kiểm tra giá dự kiến rồi xác nhận đặt đơn.</p><form id="form" class="card"><div class="mutation-grid"><label>Bước 1 · Danh mục<select id="orderCategory"><option value="">Tất cả danh mục</option></select></label><label>Bước 2 · Dịch vụ<select name="serviceId" id="service" required></select></label><label>Bước 3 · Liên kết<input name="link" type="url" placeholder="https://..." required></label><label>Bước 4 · Số lượng<input name="quantity" id="quantity" type="number" min="1" required></label></div><section id="estimate" class="card recent">Chọn dịch vụ và nhập số lượng để xem giá.</section><button id="submitOrder">Bước 6 · Xác nhận đặt đơn</button></form><section class="card recent"><div class="mutation-grid"><label>Tìm đơn<input id="orderSearch" placeholder="Mã đơn hoặc liên kết"></label><label>Trạng thái<select id="orderStatus"><option value="">Tất cả</option><option>PENDING</option><option>PROCESSING</option><option>IN_PROGRESS</option><option>COMPLETED</option><option>PARTIAL</option><option>FAILED</option><option>CANCELED</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Dịch vụ / Liên kết</th><th>Trạng thái</th><th>Số lượng</th><th>Giá</th><th>Ngày tạo</th></tr></thead><tbody id="rows"><tr><td colspan="6" class="empty">Đang tải…</td></tr></tbody></table></div><div class="pager"><button id="previous">Trước</button><span id="pageLabel">Trang 1</span><button id="next">Sau</button></div></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};let page=1,pages=1,catalog=[],orders=[];const price=(rate,q)=>{const [w,f='']=String(rate).split('.'),units=BigInt(w)*100000000n+BigInt(f.padEnd(8,'0').slice(0,8)),total=units*BigInt(q)/1000n;return String(total/100000000n)+'.'+String(total%100000000n).padStart(8,'0')};function serviceOptions(){const category=orderCategory.value;service.innerHTML=catalog.filter(x=>!category||x.categoryId===category).map(x=>'<option value="'+x.id+'">'+x.name+' · '+x.rate+'/1000</option>').join('');preview()}function preview(){const item=catalog.find(x=>x.id===service.value),q=Number(quantity.value);if(!item){estimate.textContent='Chưa có dịch vụ phù hợp.';submitOrder.disabled=true;return}quantity.min=item.min;quantity.max=item.max;const valid=Number.isInteger(q)&&q>=item.min&&q<=item.max;estimate.innerHTML='<b>'+item.name+'</b><p>Giá / 1000: '+item.rate+' · Tối thiểu '+item.min+' · Tối đa '+item.max+'</p><p>Bảo hành: '+(item.refill?'Có':'Không')+' · Hủy đơn: '+(item.cancel?'Có':'Không')+'</p><p class="value">Giá dự kiến: '+(valid?price(item.rate,q):'Nhập số lượng hợp lệ')+'</p>';submitOrder.disabled=!valid}function render(){const term=orderSearch.value.trim().toLowerCase(),status=orderStatus.value,filtered=orders.filter(x=>(!term||x.publicId.toLowerCase().includes(term)||String(x.link||'').toLowerCase().includes(term))&&(!status||x.status===status));rows.innerHTML=filtered.length?filtered.map(x=>'<tr><td><a href="/orders/'+x.publicId+'">'+x.publicId.slice(0,8)+'</a></td><td><b>'+(x.service?.name||'Dịch vụ')+'</b><br><small>'+x.link+'</small></td><td><span class="pill">'+statusText(x.status)+'</span></td><td>'+x.quantity+'</td><td>'+x.charge+'</td><td>'+new Date(x.createdAt).toLocaleString('vi-VN')+'</td></tr>').join(''):'<tr><td colspan="6" class="empty">Không có đơn hàng phù hợp.</td></tr>'}async function load(){try{const data=await Promise.all([call('/api/v1/customer/catalog?page=1&limit=100'),call('/api/v1/customer/orders?page='+page+'&limit=20')]),catalogData=data[0],orderData=data[1];catalog=catalogData.services;orders=orderData.items;orderCategory.innerHTML='<option value="">Tất cả danh mục</option>'+catalogData.categories.map(x=>'<option value="'+x.id+'">'+x.name+'</option>').join('');serviceOptions();pages=Math.max(1,orderData.pages);pageLabel.textContent='Trang '+page+' / '+pages;previous.disabled=page<=1;next.disabled=page>=pages;render()}catch(error){message.textContent=error.message}}orderCategory.onchange=serviceOptions;service.onchange=preview;quantity.oninput=preview;orderSearch.oninput=render;orderStatus.onchange=render;previous.onclick=()=>{if(page>1){page--;load()}};next.onclick=()=>{if(page<pages){page++;load()}};form.onsubmit=async e=>{e.preventDefault();if(submitOrder.disabled)return;if(!confirm('Xác nhận đặt đơn với thông tin đã nhập?'))return;submitOrder.disabled=true;message.textContent='Đang tạo đơn…';try{await call('/api/v1/customer/orders',{method:'POST',headers:{'idempotency-key':'web:'+crypto.randomUUID()},body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();message.textContent='Đã tạo đơn thành công.';page=1;await load()}catch(error){message.textContent=error.message}finally{submitOrder.disabled=false}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load()`;
  return layout("Đơn hàng", body, script);
}

export function featurePage(
  kind: "api" | "deposit" | "support" | "notifications",
  api: string,
) {
  const cfg = {
    api: ["API v2", "Quản lý API key reseller"],
    deposit: ["Nạp tiền", "Tạo và theo dõi deposit"],
    support: ["Hỗ trợ", "Ticket của bạn"],
    notifications: ["Thông báo", "Notification center"],
  }[kind];
  const body = `<div class="shell"><aside class="side">${customerNavigation(kind === "api" ? "/api-docs" : kind === "deposit" ? "/deposit" : kind === "support" ? "/support" : "/notifications")}</aside><main><h1>${cfg[0]}</h1><p class="muted">${cfg[1]}</p><section class="card" id="content">Đang tải…</section><div class="error" id="message"></div></main></div>`;
  const scripts = {
    api: `async function load(){const keys=await call('/api/v1/customer/api-keys');content.innerHTML='<div class="notice"><b>Raw API key chỉ hiển thị một lần.</b> Copy và lưu trong secret manager.</div><button id="create">Generate / regenerate key</button><div id="raw"></div>'+keys.map(x=>'<p><code>'+x.keyPrefix+'…</code> '+(x.active?'Active <button data-revoke="'+x.id+'">Revoke</button>':'Revoked')+'</p>').join('')+'<h2>API v2</h2><pre>POST /api/v2\\nX-API-Key: smm_...\\nContent-Type: application/json\\nIdempotency-Key: unique-request-id\\n\\n{"action":"services"}\\n{"action":"add","service":"SERVICE_ID","link":"https://example.com/post","quantity":100,"idempotency_key":"order-123"}\\n{"action":"status","order":"ORDER_ID"}\\n{"action":"status","orders":"1,2,3"}\\n{"action":"refill","order":"ORDER_ID","idempotency_key":"refill-123"}\\n{"action":"refill_status","refill":"REFILL_ID"}\\n{"action":"cancel","order":"ORDER_ID","idempotency_key":"cancel-123"}\\n{"action":"balance"}\\n\\nForm encoded: action=balance&key=smm_...\\n\\nErrors: 400 invalid request · 401 invalid key · 429 rate limited\\n429 includes Retry-After; limits are distributed per API key and IP.</pre>';const create=byId('create'),raw=byId('raw');create.onclick=async()=>{if(keys.some(x=>x.active)&&!confirm('Regenerate sẽ revoke key hiện tại. Tiếp tục?'))return;const x=await call('/api/v1/customer/api-keys',{method:'POST',body:'{}'});raw.innerHTML='<code id="rawKey">'+x.key+'</code> <button id="copyKey">Copy</button>';const copyKey=byId('copyKey');copyKey.onclick=()=>navigator.clipboard.writeText(x.key)};document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{if(confirm('Revoke API key?')){await call('/api/v1/customer/api-keys/'+b.dataset.revoke+'/disable',{method:'POST',body:'{}'});load()}})}`,
    deposit: `async function load(){const [methods,rows]=await Promise.all([call('/api/v1/customer/payment-methods'),call('/api/v1/customer/deposits')]);content.innerHTML='<select id="method">'+methods.map(x=>'<option value="'+x.id+'">'+x.name+'</option>').join('')+'</select><input id="amount" placeholder="Amount"><button id="create">Tạo deposit</button>'+rows.map(x=>'<p><a href="/deposit/'+x.id+'">'+x.code+'</a> · '+statusText(x.status)+' · '+x.grossAmount+'</p>').join('');const method=byId('method'),amount=byId('amount'),create=byId('create');create.onclick=async()=>{const x=await call('/api/v1/customer/deposits',{method:'POST',body:JSON.stringify({paymentMethodId:method.value,amount:amount.value})});location.href='/deposit/'+x.id}}`,
    support: `async function load(){const rows=await call('/api/v1/customer/tickets');content.innerHTML='<label>Tiêu đề<input id="subject" placeholder="Bạn cần hỗ trợ vấn đề gì?"></label><label>Nội dung<textarea id="body" placeholder="Mô tả chi tiết để chúng tôi hỗ trợ nhanh hơn"></textarea></label><button id="create">Gửi yêu cầu hỗ trợ</button><h2>Yêu cầu của bạn</h2>'+rows.map(x=>'<p><a href="/support/'+x.id+'">#'+x.id+' '+x.subject+'</a> · '+statusText(x.status)+'</p>').join('');const subject=byId('subject'),body=byId('body'),create=byId('create');create.onclick=async()=>{create.disabled=true;try{const ticket=await call('/api/v1/customer/tickets',{method:'POST',body:JSON.stringify({subject:subject.value,category:'GENERAL',message:body.value})});location.href='/support/'+ticket.id}catch(error){message.textContent=error.message;create.disabled=false}}}`,
    notifications: `async function load(){const [rows,count]=await Promise.all([call('/api/v1/customer/notifications'),call('/api/v1/customer/notifications/unread-count')]);content.innerHTML='<div class="section-title"><b>'+count.unread+' thông báo chưa đọc</b><button id="readAll" style="width:auto;margin:0">Đánh dấu tất cả đã đọc</button></div>'+(rows.length?rows.map(x=>'<article class="notice"><div><b>'+x.title+'</b><p>'+x.body+'</p></div>'+(x.readAt?'':'<button data-id="'+x.id+'" style="width:auto;margin:0">Đánh dấu đã đọc</button>')+'</article>').join(''):'<p class="empty">Bạn chưa có thông báo.</p>');const readAll=byId('readAll');readAll.disabled=count.unread===0;readAll.onclick=async()=>{await call('/api/v1/customer/notifications/read-all',{method:'POST',body:'{}'});load()};document.querySelectorAll('[data-id]').forEach(b=>b.onclick=async()=>{await call('/api/v1/customer/notifications/'+b.dataset.id+'/read',{method:'POST',body:'{}'});load()})}`,
  };
  return layout(
    cfg[0]!,
    body,
    `${client(api)};${scripts[kind]};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`,
  );
}
export function ticketDetailPage(api: string, id: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/support")}</aside><main><a href="/support">← Danh sách hỗ trợ</a><h1>Chi tiết yêu cầu #${id}</h1><section id="ticket" class="card skeleton">Đang tải…</section><section class="card recent"><label>Phản hồi<textarea id="reply" placeholder="Nhập nội dung phản hồi"></textarea></label><button id="send">Gửi phản hồi</button></section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};async function load(){const x=await call('/api/v1/customer/tickets/${id}');ticket.classList.remove('skeleton');ticket.innerHTML='<h2>'+x.subject+'</h2><p>Trạng thái: <b>'+statusText(x.status)+'</b></p><div>'+x.messages.map(m=>'<article class="notice"><div><p>'+m.message+'</p><small>'+new Date(m.createdAt).toLocaleString('vi-VN')+'</small></div></article>').join('')+'</div>'}send.onclick=async()=>{send.disabled=true;message.textContent='Đang gửi…';try{await call('/api/v1/customer/tickets/${id}/reply',{method:'POST',body:JSON.stringify({message:reply.value})});reply.value='';message.textContent='Đã gửi phản hồi.';await load()}catch(error){message.textContent=error.message}finally{send.disabled=false}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(error=>message.textContent=error.message)`;
  return layout("Chi tiết hỗ trợ", body, script);
}
export function orderDetailPage(api: string, id: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/orders")}</aside><main><h1>Order detail</h1><section class="card" id="detail">Loading…</section><section class="card recent"><h2>Lifecycle</h2><div id="history"></div></section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};async function load(){const x=await call('/api/v1/customer/orders/${id}');detail.innerHTML='<p><b>'+x.publicId+'</b> · '+statusText(x.status)+'</p><p>'+x.link+'</p><p>Quantity '+x.quantity+' · Charge '+x.charge+' · Refunded '+x.refundedAmount+'</p><p>Start '+(x.startCount??'—')+' · Remains '+(x.remains??'—')+'</p><button id="refill">Refill</button><button id="cancel">Cancel</button>';history.innerHTML=x.history.map(h=>'<p>'+h.fromStatus+' → '+h.toStatus+' · '+new Date(h.createdAt).toLocaleString()+'</p>').join('')||'<p class="empty">No history</p>';for(const a of ['refill','cancel'])byId(a).onclick=async()=>{if(!confirm('Confirm '+a+'?'))return;try{await call('/api/v1/customer/orders/${id}/'+a,{method:'POST',headers:{'idempotency-key':a+':'+crypto.randomUUID()},body:'{}'});message.textContent='Request accepted';load()}catch(e){message.textContent=e.message}}}logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`;
  return layout("Order detail", body, script);
}
export function depositDetailPage(api: string, id: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/deposit")}</aside><main><a href="/deposit">← Deposits</a><h1>Deposit</h1><section class="card" id="detail">Loading…</section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};let timer,delay=5000,stopped=false;const terminal=new Set(['PAID','FAILED','EXPIRED','CANCELED','MANUAL_REVIEW']);async function poll(){if(stopped)return;try{const x=await call('/api/v1/customer/deposits/${id}'),p=x.payment;detail.innerHTML='<p class="value">'+x.grossAmount+' '+x.sourceCurrency+'</p><p>Fee '+x.feeAmount+' · Net '+x.netAmount+'</p><p>Method '+(x.paymentMethod?.name||'—')+' · Trạng thái <b>'+statusText(x.status)+'</b></p>'+(p&&p.available?'<img alt="VietQR" style="max-width:300px;width:100%" src="'+p.qrUrl+'"><p>Bank <b>'+p.bankName+'</b></p><p>Account <b>'+p.accountNumber+'</b> · '+p.accountName+'</p><p>Transfer content <code>'+p.transferContent+'</code> <button id="copy">Copy</button></p>':'<p>Bank payment configuration unavailable. Do not transfer until enabled.</p>')+'<p>Transfer code '+x.code+'</p><p>Created '+new Date(x.createdAt).toLocaleString()+'</p><p>Expires '+new Date(x.expiresAt).toLocaleString()+'</p><p>Paid '+(x.paidAt?new Date(x.paidAt).toLocaleString():'—')+'</p>';if(p&&p.available)byId('copy').onclick=()=>navigator.clipboard.writeText(p.transferContent);if(terminal.has(x.status)){stopped=true;clearTimeout(timer)}else{delay=Math.min(30000,Math.round(delay*1.4));timer=setTimeout(poll,delay)}}catch(e){message.textContent=e.message;delay=Math.min(30000,delay*2);timer=setTimeout(poll,delay)}}window.addEventListener('pagehide',()=>{stopped=true;clearTimeout(timer)});logout.onclick=async e=>{e.preventDefault();stopped=true;clearTimeout(timer);await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};poll()`;
  return layout("Deposit detail", body, script);
}
export function adminDepositsPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/deposits")}</aside><main><h1>Deposits</h1><select id="status"><option value="">All</option><option>PENDING</option><option>PAID</option><option>MANUAL_REVIEW</option><option>FAILED</option></select><section class="card table-wrap"><table><thead><tr><th>User</th><th>Code</th><th>Method</th><th>Amount</th><th>Trạng thái</th><th>Transaction</th></tr></thead><tbody id="rows"></tbody></table></section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};async function load(){const x=await call('/api/v1/admin/deposits'+(status.value?'?status='+encodeURIComponent(status.value):''));rows.innerHTML=x.map(d=>'<tr><td>'+d.user.username+'<br><small>'+d.user.email+'</small></td><td>'+d.code+'</td><td>'+d.paymentMethod.name+'</td><td>'+d.grossAmount+' '+d.sourceCurrency+'</td><td>'+d.status+'</td><td>'+(d.externalTransactionId||'—')+'</td></tr>').join('')||'<tr><td colspan="6">No deposits</td></tr>'}status.onchange=load;logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`;
  return layout("Admin deposits", body, script);
}
export function adminSupportPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/support")}</aside><main><h1>Support inbox</h1><section class="card mutation-grid"><input id="search" placeholder="Search"><select id="status"><option value="">All</option><option>OPEN</option><option>ANSWERED</option><option>CUSTOMER_REPLY</option><option>CLOSED</option></select></section><section id="items" class="card recent">Loading…</section><section id="conversation" class="card recent"></section><div class="error" id="message"></div></main></div>`;
  const script = `${client(api)};async function load(){const q=new URLSearchParams();if(search.value.trim())q.set('search',search.value.trim());if(status.value)q.set('status',status.value);const x=await call('/api/v1/admin/tickets?'+q);items.innerHTML=x.items.map(t=>'<button data-id="'+t.id+'">#'+t.id+' '+t.subject+' · '+t.status+'</button>').join('')||'Empty';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openTicket(b.dataset.id))}async function openTicket(id){const x=await call('/api/v1/admin/tickets/'+id);conversation.innerHTML='<h2>'+x.subject+'</h2>'+x.messages.map(m=>'<p class="'+(m.internal?'negative':'')+'">'+m.message+(m.internal?' [internal]':'')+'</p>').join('')+'<textarea id="reply"></textarea><label><input id="internal" type="checkbox"> Internal note</label><button id="send">Reply</button><select id="newStatus"><option>OPEN</option><option>ANSWERED</option><option>CLOSED</option></select><button id="change">Change status</button>';const reply=byId('reply'),internal=byId('internal'),send=byId('send'),newStatus=byId('newStatus'),change=byId('change');send.onclick=async()=>{await call('/api/v1/admin/tickets/'+id+'/reply',{method:'POST',body:JSON.stringify({message:reply.value,internal:internal.checked})});openTicket(id)};change.onclick=async()=>{await call('/api/v1/admin/tickets/'+id+'/status',{method:'POST',body:JSON.stringify({status:newStatus.value})});load()}}search.oninput=()=>load();status.onchange=load;logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`;
  return layout("Support inbox", body, script);
}

const adminNavigation = (active: string) =>
  `<div class="brand"><span class="mark">N</span>Nexus Admin</div><nav><small class="muted">TỔNG QUAN</small>${navLink(active, "/admin", "Tổng quan")}<small class="muted">VẬN HÀNH</small>${navLink(active, "/admin/users", "Người dùng")}${navLink(active, "/admin/orders", "Đơn hàng")}${navLink(active, "/admin/catalog", "Dịch vụ")}${navLink(active, "/admin/providers", "Nhà cung cấp")}<small class="muted">TÀI CHÍNH</small>${navLink(active, "/admin/wallet", "Ví người dùng")}${navLink(active, "/admin/payments", "Thanh toán")}${navLink(active, "/admin/deposits", "Nạp tiền")}${navLink(active, "/admin/reports", "Báo cáo")}<small class="muted">HỖ TRỢ</small>${navLink(active, "/admin/support", "Yêu cầu hỗ trợ")}<small class="muted">HỆ THỐNG</small>${navLink(active, "/admin/logs", "Nhật ký")}${navLink(active, "/admin/settings", "Cài đặt")}<a href="#" id="logout">Đăng xuất</a></nav>`;

export function adminModulePage(
  api: string,
  kind: "users" | "orders" | "reports" | "logs" | "settings",
) {
  const titles = {
      users: "User management",
      orders: "Order operations",
      reports: "Reports",
      logs: "Logs & audit",
      settings: "General settings",
    },
    body = `<div class="shell"><aside class="side">${adminNavigation("/admin/" + kind)}</aside><main><h1>${titles[kind]}</h1><section class="card mutation-grid" id="filters"></section><section class="card recent" id="content">Loading…</section><div id="message" class="error"></div></main></div>`,
    scripts = {
      users: `filters.innerHTML='<input id="search" placeholder="Email, username or ID"><select id="status"><option value="">All statuses</option><option>ACTIVE</option><option>PENDING</option><option>BANNED</option></select><select id="role"><option value="">All roles</option><option>USER</option><option>RESELLER</option><option>SUPPORT</option><option>STAFF</option><option>ADMIN</option><option>SUPER_ADMIN</option></select><button id="apply">Search</button>';const search=byId('search'),status=byId('status'),role=byId('role'),apply=byId('apply');async function load(page=1){const q=new URLSearchParams({page:String(page)});if(search.value.trim())q.set('search',search.value.trim());if(status.value)q.set('status',status.value);if(role.value)q.set('role',role.value);const x=await call('/api/v1/admin/users?'+q);content.innerHTML='<div class="table-wrap"><table><thead><tr><th>User</th><th>Trạng thái</th><th>Verified</th><th>Created</th></tr></thead><tbody>'+x.items.map(u=>'<tr><td><a href="/admin/users/'+u.id+'">'+u.username+'</a><br><small>'+u.email+'</small></td><td>'+u.status+'</td><td>'+(u.emailVerifiedAt?'Yes':'No')+'</td><td>'+new Date(u.createdAt).toLocaleString()+'</td></tr>').join('')+'</tbody></table></div><div class="pager"><button id="prevPage">Previous</button><span>Page '+x.page+' / '+Math.max(1,x.pages)+'</span><button id="nextPage">Next</button></div>';const prevPage=byId('prevPage'),nextPage=byId('nextPage');prevPage.disabled=x.page<=1;nextPage.disabled=x.page>=x.pages;prevPage.onclick=()=>load(x.page-1);nextPage.onclick=()=>load(x.page+1)}apply.onclick=()=>load();load()`,
      orders: `filters.innerHTML='<input id="search" placeholder="Order ID or link"><select id="status"><option value="">All statuses</option><option>PENDING</option><option>PROCESSING</option><option>IN_PROGRESS</option><option>COMPLETED</option><option>PARTIAL</option><option>FAILED</option></select><button id="apply">Filter</button>';const search=byId('search'),status=byId('status'),apply=byId('apply');async function load(page=1){const q=new URLSearchParams({page:String(page)});if(search.value.trim())q.set('search',search.value.trim());if(status.value)q.set('status',status.value);const x=await call('/api/v1/admin/orders?'+q);content.innerHTML='<div class="table-wrap"><table><thead><tr><th>Order</th><th>User</th><th>Trạng thái</th><th>Charge</th><th>Profit</th></tr></thead><tbody>'+x.items.map(o=>'<tr><td><a href="/admin/orders/'+o.publicId+'">'+o.publicId.slice(0,8)+'</a></td><td>'+o.userId+'</td><td>'+o.status+'</td><td>'+o.charge+'</td><td>'+o.profit+'</td></tr>').join('')+'</tbody></table></div><div class="pager"><button id="prevPage">Previous</button><span>Page '+x.page+' / '+Math.max(1,x.pages)+'</span><button id="nextPage">Next</button></div>';const prevPage=byId('prevPage'),nextPage=byId('nextPage');prevPage.disabled=x.page<=1;nextPage.disabled=x.page>=x.pages;prevPage.onclick=()=>load(x.page-1);nextPage.onclick=()=>load(x.page+1)}apply.onclick=()=>load();load()`,
      reports: `filters.innerHTML='<label>Khoảng thời gian<select id="period"><option value="today">Hôm nay</option><option value="7" selected>7 ngày</option><option value="30">30 ngày</option><option value="custom">Tùy chọn</option></select></label><label>Từ ngày<input id="from" type="date"></label><label>Đến ngày<input id="to" type="date"></label><button id="apply">Xem báo cáo</button><a id="exportCsv" class="card">Xuất CSV</a>';const period=byId('period'),from=byId('from'),to=byId('to'),apply=byId('apply'),exportCsv=byId('exportCsv');function range(){if(period.value==='custom')return;const now=new Date(),days=period.value==='today'?0:Number(period.value)-1,start=new Date(now);start.setDate(now.getDate()-days);from.value=start.toISOString().slice(0,10);to.value=now.toISOString().slice(0,10)}async function load(){range();const q=new URLSearchParams();if(from.value)q.set('from',from.value);if(to.value)q.set('to',to.value);exportCsv.href=API+'/api/v1/admin/reports.csv?'+q;const x=await call('/api/v1/admin/reports?'+q);content.innerHTML='<div class="cards">'+[['Doanh thu',x.money.revenue],['Chi phí nhà cung cấp',x.money.providerCost],['Lợi nhuận',x.money.profit],['Tiền nạp',x.money.deposits],['Tổng đơn',x.orders.total],['Đơn thất bại',x.orders.failed],['Đơn một phần',x.orders.partial],['Đã hoàn tiền',x.orders.refunded],['Người dùng mới',x.users]].map(k=>'<article class="card"><span class="muted">'+k[0]+'</span><div class="value">'+k[1]+'</div></article>').join('')+'</div><h2>Dịch vụ nổi bật</h2>'+x.topServices.map(s=>'<p>'+s.serviceId+' · '+s._count+' đơn · '+s.charge+'</p>').join('')+'<h2>Hiệu suất nhà cung cấp</h2>'+x.providerPerformance.map(p=>'<p>'+p.providerId+' · '+p.orders+' đơn · Lợi nhuận '+p.profit+'</p>').join('')+'<p>Nạp tiền cần kiểm tra: '+x.deposits.manualReview+'</p>'}period.onchange=()=>{from.disabled=to.disabled=period.value!=='custom';range()};apply.onclick=load;load()`,
      logs: `filters.innerHTML='<select id="kind"><option value="audit">Audit</option><option value="system">System</option><option value="webhook">Webhook</option></select><button id="apply">Load</button>';const kind=byId('kind'),apply=byId('apply');async function load(){const x=await call('/api/v1/admin/logs?kind='+kind.value);content.innerHTML=x.map(r=>'<article><b>'+(r.action||r.event||r.source)+'</b><p>'+(r.resource||r.message||r.status)+'</p><small>'+new Date(r.createdAt).toLocaleString()+'</small></article>').join('')||'<p class="empty">No logs</p>'}apply.onclick=load;load()`,
      settings: `filters.innerHTML='';async function load(){const rows=await call('/api/v1/admin/settings'),v=Object.fromEntries(rows.map(x=>[x.key,x.value]));content.innerHTML='<label>Site name<input id="siteName" value="'+(v.siteName||'Nexus Panel')+'"></label><label>Currency<input id="currency" value="'+(v.currency||'USD')+'"></label><label>Timezone<input id="timezone" value="'+(v.timezone||'UTC')+'"></label><label><input id="registrationEnabled" type="checkbox" '+(v.registrationEnabled!==false?'checked':'')+'> Registration enabled</label><label><input id="maintenanceMode" type="checkbox" '+(v.maintenanceMode?'checked':'')+'> Maintenance mode</label><button id="save">Save</button>';const siteName=byId('siteName'),currency=byId('currency'),timezone=byId('timezone'),registrationEnabled=byId('registrationEnabled'),maintenanceMode=byId('maintenanceMode'),save=byId('save');save.onclick=async()=>{await call('/api/v1/admin/settings',{method:'POST',body:JSON.stringify({siteName:siteName.value,currency:currency.value,timezone:timezone.value,registrationEnabled:registrationEnabled.checked,maintenanceMode:maintenanceMode.checked})});message.textContent='Settings saved'}}load()`,
    };
  return layout(
    titles[kind],
    body,
    `${client(api)};${scripts[kind]};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'}`,
  );
}

export function adminRecordPage(
  api: string,
  kind: "users" | "orders",
  id: string,
) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/" + kind)}</aside><main><a href="/admin/${kind}">← Back</a><h1>${kind === "users" ? "User detail" : "Order detail"}</h1><section id="content" class="card">Loading…</section><div id="message" class="error"></div></main></div>`,
    script =
      kind === "users"
        ? `async function load(){const u=await call('/api/v1/admin/users/${id}');content.innerHTML='<h2>'+u.username+'</h2><p>'+u.email+' · '+u.status+'</p><p>Wallet '+(u.wallet?u.wallet.balance+' '+u.wallet.currency:'—')+'</p><p>Roles '+u.roles.map(r=>r.code).join(', ')+'</p><p>Orders '+u.counts.orders+' · Deposits '+u.counts.deposits+' · Tickets '+u.counts.tickets+' · Sessions '+u.counts.activeSessions+'</p><button id="ban">'+(u.status==='BANNED'?'Unban':'Ban')+'</button><button id="revoke">Revoke sessions</button>';const ban=byId('ban'),revoke=byId('revoke');ban.onclick=async()=>{if(confirm('Confirm status change?')){await call('/api/v1/admin/users/${id}',{method:'POST',body:JSON.stringify({status:u.status==='BANNED'?'ACTIVE':'BANNED'})});load()}};revoke.onclick=async()=>{if(confirm('Revoke all sessions?')){await call('/api/v1/admin/users/${id}/revoke-sessions',{method:'POST',body:'{}'});load()}}}load()`
        : `async function load(){const o=await call('/api/v1/admin/orders/${id}');content.innerHTML='<h2>'+o.publicId+'</h2><p>'+o.service.name+' · '+o.status+'</p><p>User '+o.user.username+' · '+o.user.email+'</p><p>'+o.link+' · Quantity '+o.quantity+'</p><p>Charge '+o.charge+' · Cost '+o.providerCost+' · Profit '+o.profit+'</p><p>Start '+(o.startCount??'—')+' · Remains '+(o.remains??'—')+'</p><h3>History</h3>'+o.history.map(h=>'<p>'+h.fromStatus+' → '+h.toStatus+'</p>').join('')+'<h3>Provider logs</h3>'+o.providerLogs.map(l=>'<p>'+l.operation+' · '+l.status+' · '+(l.errorCode||'OK')+'</p>').join('')}load()`;
  return layout(
    kind === "users" ? "User detail" : "Order detail",
    body,
    `${client(api)};${script};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'}`,
  );
}

export function accountPage(api: string) {
  const body = `<div class="shell"><aside class="side">${customerNavigation("/account")}</aside><main><h1>Tài khoản & bảo mật</h1><section id="profile" class="card skeleton">Đang tải…</section><section class="card recent"><h2>Đổi mật khẩu</h2><form id="passwordForm" class="mutation-grid"><label>Mật khẩu hiện tại<input name="currentPassword" type="password" required></label><label>Mật khẩu mới<input name="newPassword" type="password" minlength="12" required></label><button>Đổi mật khẩu</button></form></section><section class="card recent"><div class="section-title"><h2>Phiên đăng nhập</h2><button id="logoutOthers" style="width:auto;margin:0">Đăng xuất phiên khác</button></div><div id="sessions">Đang tải…</div></section><section class="card recent"><a href="/api-docs">Quản lý API keys →</a></section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};async function load(){const [me,data]=await Promise.all([call('/api/v1/me'),call('/api/v1/auth/sessions')]);profile.classList.remove('skeleton');profile.innerHTML='<h2>'+me.user.username+'</h2><p>'+me.user.email+'</p><p>Email verification: <b>'+(me.user.emailVerified?'Verified':'Not verified')+'</b></p><p>Roles: '+me.roles.join(', ')+'</p>';sessions.innerHTML=data.sessions.map(s=>'<article class="notice"><div><b>'+escapeHtml(s.userAgent||'Unknown device')+'</b><p>'+escapeHtml(s.ipAddress||'Unknown IP')+' · '+new Date(s.createdAt).toLocaleString()+'</p></div><button style="width:auto;margin:0" data-session="'+s.id+'">Revoke</button></article>').join('')||'<p class="empty">Không có active session.</p>';document.querySelectorAll('[data-session]').forEach(b=>b.onclick=async()=>{if(confirm('Revoke session?')){await call('/api/v1/auth/sessions/'+b.dataset.session+'/revoke',{method:'POST',body:'{}'});load()}})}function escapeHtml(v){const d=document.createElement('div');d.textContent=String(v);return d.innerHTML}passwordForm.onsubmit=async e=>{e.preventDefault();try{await call('/api/v1/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(passwordForm)))});passwordForm.reset();message.textContent='Đã đổi mật khẩu.'}catch(e){message.textContent=e.message}};logoutOthers.onclick=async()=>{if(confirm('Đăng xuất tất cả phiên khác?')){await call('/api/v1/auth/logout-others',{method:'POST',body:'{}'});message.textContent='Đã revoke các phiên khác.';load()}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`;
  return layout("Tài khoản", body, script);
}

export function adminPaymentsPage(api: string) {
  const body = `<div class="shell"><aside class="side">${adminNavigation("/admin/payments")}</aside><main><h1>Payment settings</h1><p class="muted">Secrets are encrypted and are never returned after saving.</p><form id="form" class="card mutation-grid"><label><input name="cassoEnabled" id="cassoEnabled" type="checkbox"> Tự động xác nhận chuyển khoản qua Casso<small class="muted">Bật để nhận và đối soát giao dịch từ webhook Casso.</small></label><label>Casso API key<input name="cassoApiKey" type="password" autocomplete="new-password" placeholder="Để trống để giữ giá trị hiện tại"></label><label>Webhook secure token<input name="cassoWebhookSecureToken" type="password" autocomplete="new-password" placeholder="Để trống để giữ giá trị hiện tại"></label><label>Bank name<input name="bankName"></label><label>Bank BIN<input name="bankBin"></label><label>Account number<input name="bankAccountNumber"></label><label>Account name<input name="bankAccountName"></label><label>VietQR Client ID<input name="vietQrClientId" type="password" placeholder="Để trống để giữ giá trị hiện tại"><small class="muted">Thông tin xác thực được mã hóa khi lưu.</small></label><label>VietQR API key<input name="vietQrApiKey" type="password" placeholder="Để trống để giữ giá trị hiện tại"><small class="muted">Không bao giờ hiển thị lại khóa nguyên bản.</small></label><button>Save encrypted settings</button></form><section id="status" class="card recent skeleton">Loading…</section><div id="message" class="error"></div></main></div>`;
  const script = `${client(api)};let current;async function load(){current=await call('/api/v1/admin/payment-settings');status.classList.remove('skeleton');status.innerHTML='<p>Webhook URL <code>'+current.webhookUrl+'</code></p><p>Casso API key: '+(current.cassoApiKey?.masked||'Not configured')+'</p><p>Webhook token: '+(current.cassoWebhookSecureToken?.masked||'Not configured')+'</p>';for(const k of ['bankName','bankBin','bankAccountNumber','bankAccountName'])if(form.elements[k])form.elements[k].value=current[k]||'';cassoEnabled.checked=current.cassoEnabled===true}form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));data.cassoEnabled=cassoEnabled.checked;for(const k of ['cassoApiKey','cassoWebhookSecureToken','vietQrClientId','vietQrApiKey'])if(!data[k])delete data[k];try{await call('/api/v1/admin/payment-settings',{method:'POST',body:JSON.stringify(data)});message.textContent='Payment settings saved.';form.reset();load()}catch(e){message.textContent=e.message}};logout.onclick=async e=>{e.preventDefault();await call('/api/v1/auth/logout',{method:'POST',body:'{}'});location.href='/login'};load().catch(e=>message.textContent=e.message)`;
  return layout("Payment settings", body, script);
}
